{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"rent_increase_limits","lifecycle":"enacted","title":"Chapter 40P prohibition on municipal rent control","requirement":"No city or town may enact, maintain or enforce rent control of any kind; only a city or town that accepts this chapter may adopt rent control regulation, and after six months owner compliance with that regulation is entirely voluntary.","key_value":null,"coverage_conditions":"All cities and towns in Massachusetts. Regulation adopted under the chapter may not apply to a rental unit owned by a person or entity owning fewer than 10 rental units or a unit with fair market rent over $400.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exemption for owners of fewer than 10 rental units; units with fair market rent over $400 excluded"},"exemptions":"Regulation may not apply to rental units owned by a person or entity owning fewer than 10 rental units, or to units with a fair market rent exceeding $400; owner compliance becomes voluntary after six months.","penalty":null,"effective_date":null,"citation":"G.L. c. 40P, § 4","quoted_span":"No city or town may enact, maintain or enforce rent control of any kind, except that any city or town that accepts this chapter may adopt rent control regulation that provides:","interaction":"Only a city or town that accepts chapter 40P may adopt rent control regulation.","confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"just_cause_eviction","lifecycle":"enacted","title":"Chapter 40P limit on municipal regulation of evictions","requirement":"Rent control regulation adopted under this chapter may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from such regulation.","key_value":null,"coverage_conditions":"Rent control regulation adopted by a city or town that accepts this chapter; such regulation may not cover occupancy, services, evictions, condominium conversion or removal from regulation.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"G.L. c. 40P, § 4","quoted_span":"such regulation may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from such regulation","interaction":"State law bars cities or towns that accept chapter 40P from regulating evictions through rent control regulation.","confidence":0.9,"conflict_flag":false,"conflict_note":null}
